// Pinyin for search ("taile" or "tl" finds 泰勒公式). data/pinyin.json is generated by
// `npm run pinyin` (pinyin-pro, a dev dependency) and committed, so builds need no packages:
//   { "words": { "泰勒公式": "tai le gong shi", … }, "chars": { "泰": "tai", … } }
// Titles missing from "words" (new content) fall back to the per-character table.
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

let cache = null;
function table(root) {
  if (cache) return cache;
  const file = join(root, 'data/pinyin.json');
  cache = existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : { words: {}, chars: {} };
  return cache;
}

export function wordPinyin(root, s) {
  const t = table(root);
  if (t.words[s]) return t.words[s].split(' ');
  const out = [];
  let ascii = '';
  for (const ch of s) {
    if (/[a-z0-9]/i.test(ch)) { ascii += ch.toLowerCase(); continue; }
    if (ascii) { out.push(ascii); ascii = ''; }
    if (t.chars[ch]) out.push(t.chars[ch]);
  }
  if (ascii) out.push(ascii);
  return out;
}

export function toPinyin(root, strings) {
  const full = [], initials = [];
  for (const s of strings) {
    const syl = wordPinyin(root, s);
    if (!syl.length) continue;
    full.push(syl.join(''));
    initials.push(syl.map((p) => p[0]).join(''));
  }
  return { full: full.join('|'), initials: initials.join('|') };
}
